// Witness identities are the canonical typed RMN object identities used everywhere else.
import { semanticId } from "@emsenn/rmn-semantic-conformance";
import { encodeRelationalValue } from "@emsenn/rmn-semantic-conformance/relational-value";

export function digestObject(value) {
  const encoded = encodeRelationalValue(value);
  return semanticId(["ascribe", encoded.type, encoded.term]);
}

export function addressed(value) {
  const digest = digestObject(value);
  return { ...value, id: digest, digest };
}


